  const [h1, intro, sectionTitle, paragraphOne, paragraphTwo, stepOne, stepTwo, stepThree, note, faqQuestion, faqAnswer] = pack.toolTemplate;
  const [aboutTitle, aboutDescription, aboutH1, aboutIntro, aboutHeading, aboutText] = pack.pages.about;
